package net.officefloor.hq.app.sheet;

import jakarta.persistence.CollectionTable;
import jakarta.persistence.Column;
import jakarta.persistence.ElementCollection;
import jakarta.persistence.Entity;
import jakarta.persistence.EntityListeners;
import jakarta.persistence.FetchType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.MapKeyColumn;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.Instant;
import java.time.LocalDate;
import java.time.temporal.ChronoUnit;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.TreeMap;
import net.officefloor.hq.app.history.History;

/** A sheet, chosen by its id. Everything else in the app is kept per sheet. */
@Entity
@EntityListeners(History.class)
@Table(name = "sheet")
public class Sheet {

    public static final String FLOOR = "floor";
    public static final String LATE_PCT = "late-pct";
    public static final String TERMS = "terms";
    public static final String GRACE = "grace";
    public static final String CLERK_LIMIT = "clerk-limit";
    public static final String CAP = "cap";
    public static final String PROOF_THRESHOLD = "proof-threshold";
    public static final String NOTE_THRESHOLD = "note-threshold";
    public static final String REVIEW_THRESHOLD = "review-threshold";
    public static final String ROUNDING = "rounding";
    /** The rounding modes a sheet can set: each value, and how it rounds. */
    public static final Map<String, RoundingMode> ROUNDING_MODES = Map.of(
            "half-up", RoundingMode.HALF_UP, "half-even", RoundingMode.HALF_EVEN);
    /** The actions the permission matrix covers, and the roles that may take each by the standing rule. */
    public static final Map<String, List<String>> STANDING_PERMISSIONS = Map.of(
            "open", List.of("clerk", "steward"), "settle", List.of("clerk", "steward"),
            "void", List.of("clerk", "steward"), "close", List.of("clerk", "steward"),
            "reassign", List.of("steward"), "reopen", List.of("steward"),
            "today", List.of("clerk", "steward"));
    private static final BigDecimal START_FLOOR = new BigDecimal("1.00");
    private static final BigDecimal START_LATE_PCT = new BigDecimal("0.00");
    private static final int START_TERMS = 14;

    @Id
    private String id;

    @Column(name = "created_by", nullable = false)
    private String createdBy;

    @Column(name = "created_at", nullable = false)
    private Instant createdAt;

    /** The sheet's today: every date decision and default date in the sheet uses it. */
    @Column(name = "today", nullable = false)
    private LocalDate today;

    /** The last plain sheet-wide number given to a claim opened on the sheet, before numbering restarted each
     *  fiscal year (see FiscalClaimSequence); 0 before the first. */
    @Column(name = "last_claim_number", nullable = false)
    private int lastClaimNumber;

    /** The number of the last bulk settle batch on the sheet; 0 before the first. */
    @Column(name = "last_settle_batch", nullable = false)
    private int lastSettleBatch;

    /** The settings that carry a figure, each value from a from-date: the floor, the late percent, the terms,
     *  each grade's terms (terms-<grade>), each grade's grace days (grace-<grade>), the clerk limit, each grade's clerk limit
     *  (clerk-limit-<grade>), the cap, the proof threshold, each grade's proof
     *  threshold (proof-threshold-<grade>), the note threshold, the review threshold and the rounding mode. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "sheet_setting", joinColumns = @JoinColumn(name = "sheet_id"))
    private List<SheetSetting> settings = new ArrayList<>();

    /** The permission matrix: for an action, the roles that may take it, comma separated; an action with none
     *  keeps the standing rule. Not dated. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "sheet_permission", joinColumns = @JoinColumn(name = "sheet_id"))
    @MapKeyColumn(name = "action")
    @Column(name = "roles", nullable = false)
    private Map<String, String> permissions = new HashMap<>();

    /** The policy date: a claim dated before it rounds half up, on or after it half to even; none means
     *  the sheet's today. */
    @Column(name = "policy_date")
    private LocalDate policyDate;

    /** Period numbering from this date: while the sheet's today is on or after it, a claim opened is numbered
     *  within its period; none means off. */
    @Column(name = "period_numbering_from")
    private LocalDate periodNumberingFrom;

    /** The grace days: when the sheet's today changes, each open period whose to-date plus these days is before
     *  the new today is closed; none means off. Not dated. */
    @Column(name = "grace_days")
    private Integer graceDays;

    /** The escalation gap: reminding a claim whose previous reminder was at least these many days before the
     *  sheet's today escalates it (once per claim); none means off. Not dated. */
    @Column(name = "escalate_after")
    private Integer escalateAfter;

    /** The mid score threshold: with the high one set, a person whose score is at or above it is MID; none
     *  means no bands. Not dated. */
    @Column(name = "score_mid")
    private Integer scoreMid;

    /** The high score threshold: with the mid one set, a person whose score is at or above it is HIGH; none
     *  means no bands. Not dated. */
    @Column(name = "score_high")
    private Integer scoreHigh;

    /** The score log switch: while on, changing the sheet's today records each person's score on the day
     *  being left. Not dated. */
    @Column(name = "score_log")
    private boolean scoreLog;

    /** The review SLA: a REVIEW claim whose review day (the sheet's today when it went to REVIEW) plus these
     *  many days is before the sheet's today is late for review; none means none. Not dated. */
    @Column(name = "review_sla")
    private Integer reviewSla;

    /** The pending SLA: a PENDING claim whose pending day (the sheet's today when it last went to PENDING) plus
     *  these many days is before the sheet's today is pending late; none means none. Not dated. */
    @Column(name = "pending_sla")
