  ownStatusCounts: Record<string, number>;
  /** Each descendant's people, with their names (name, then aliases) and figures, for trimming and counting
   *  over the whole tree. */
  people: TreeMember[];
  /** The sheet's own, likewise. */
  ownPeople: TreeMember[];
