package net.officefloor.hq.app.sheet;

import jakarta.persistence.Column;
import jakarta.persistence.Embeddable;
import java.time.LocalDate;

/** A value a setting of the sheet takes from a date on, until the next from-date of the same setting; none
 *  (null) for no limit, no cap, or a grade using the sheet's terms. */
@Embeddable
public class SheetSetting {

    @Column(name = "setting_key", nullable = false)
-- Settings that carry a figure are dated: each save records its value from a from-date, and the value in force
-- on a date is the one with the latest from-date on or before it. Keys: floor, late-pct, terms, terms-<grade>,
-- clerk-limit, cap. A value of none (blank) means no limit, no cap, or a grade using the sheet's terms.
-- Before every from-date the floor is 1.00, the late percent 0.00 and the terms 14; the others are none.
CREATE TABLE sheet_setting (
    sheet_id      VARCHAR(200) NOT NULL REFERENCES sheet (id),
    setting_key   VARCHAR(20)  NOT NULL,
    from_date     DATE         NOT NULL,
    setting_value VARCHAR(20),
    PRIMARY KEY (sheet_id, setting_key, from_date)
);

/** Sheet endpoints. The signed-in user's name comes in the X-User header. */
@RestController
@Validated
@RequestMapping("/api/sheets")
public class SheetController {

    /** A sheet as the screen shows it: its today, its clerk limit (two decimals; none for no limit) and
     *  its floor (two decimals), its terms (days), its late percent (two decimals) and its policy date (none: the sheet's today) and its period numbering from-date (none: off), the terms of each grade that has its own, and its cap (two decimals; none for no cap), and its proof threshold (two decimals; none for no threshold), and its note threshold (two decimals; none for no threshold), and its review threshold (two decimals; none for no threshold), and its grace days (none: off), and whether it is archived, and its entry date (none: off), and the number of its last settle batch (none before the first), and its pot (two decimals; none for no pot), and its parent sheet's id (none for no parent), and its fiscal start month (1 to 12), and its alert threshold (two decimals; none for off), and its rounding mode (half-up or half-even; none: by the policy date), and its escalation gap (days; none: off), and its review SLA (days; none: none), and its proof kinds (comma separated; none: none), and its default grade (none: A), and its mid and high score thresholds (none: no bands), and whether its score log is on, and its maximum of open claims per person (none: none), and its retired grades (in the order retired), and its grades (A, B and C, then those added in the order added).
     *  The dated settings show the value in force on the sheet's today; every value recorded for them is in
     *  settings. */
    public record SheetView(String id, LocalDate today, String clerkLimit, String floor, int terms, String latePct,
            LocalDate policyDate, LocalDate periodNumberingFrom, Map<String, Integer> gradeTerms, String cap,
            List<SettingView> settings, String proofThreshold, Map<String, String> permissions, Integer graceDays,
            boolean archived, String noteThreshold, LocalDate entryDate, Integer lastSettleBatch, String pot,
            String parent, int fiscalStartMonth, String alertThreshold, String rounding, String reviewThreshold, Integer escalateAfter,
            Integer reviewSla, String proofKinds, String defaultGrade, Integer scoreMid, Integer scoreHigh, boolean scoreLog, Integer maxOpen,
            List<String> retiredGrades, List<String> grades, Integer pendingSla) {

        static SheetView of(Sheet sheet) {
            return of(sheet, sheet.getGrades());
        }

        /** The sheet with the grades given: an as-of view shows the grades as they are now, as they are not
         *  dated. */
        static SheetView of(Sheet sheet, List<String> grades) {
            return new SheetView(sheet.getId(), sheet.getToday(),
                    sheet.getClerkLimit() == null ? null : sheet.getClerkLimit().toPlainString(),
                    sheet.getFloor().toPlainString(), sheet.getTerms(),
                    sheet.getLatePct().toPlainString(), sheet.getPolicyDate(),
                    sheet.getPeriodNumberingFrom(), sheet.getGradeTerms(),
                    sheet.getCap() == null ? null : sheet.getCap().toPlainString(),
                    sheet.getSettings().stream().map(SettingView::of).toList(),
                    sheet.getProofThreshold() == null ? null : sheet.getProofThreshold().toPlainString(),
                    sheet.getPermissions(), sheet.getGraceDays(), sheet.isArchived(),
                    sheet.getNoteThreshold() == null ? null : sheet.getNoteThreshold().toPlainString(),
                    sheet.getEntryDate(), sheet.getLastSettleBatch() == 0 ? null : sheet.getLastSettleBatch(),
                    sheet.getPot() == null ? null : sheet.getPot().toPlainString(), sheet.getParent(),
                    sheet.getFiscalStartMonth(),
                    sheet.getAlertThreshold() == null ? null : sheet.getAlertThreshold().toPlainString(),
                    sheet.getRoundingMode(),
                    sheet.getReviewThreshold() == null ? null : sheet.getReviewThreshold().toPlainString(),
                    sheet.getEscalateAfter(), sheet.getReviewSla(), sheet.getProofKinds(),
                    sheet.getDefaultGrade(), sheet.getScoreMid(), sheet.getScoreHigh(), sheet.isScoreLog(),
                    sheet.getMaxOpen(), sheet.getRetiredGrades(), grades, sheet.getPendingSla());
        }
    }

    /** A value recorded for a dated setting (key floor, late-pct, terms, terms-<grade>, grace-<grade>, clerk-limit, clerk-limit-<grade>, cap, proof-threshold, proof-threshold-<grade>, note-threshold, review-threshold or rounding)
     *  from a date; none for no limit, no cap, or a grade using the sheet's terms. */
    public record SettingView(String key, LocalDate from, String value) {

        static SettingView of(SheetSetting setting) {
            return new SettingView(setting.getKey(), setting.getFromDate(), setting.getValue());
        }
    }

    /** The sheet's clerk limit from a date; a missing limit means no limit, a missing date the sheet's today. */
    public record SettingsRequest(@DecimalMin("0.00") @Digits(integer = 13, fraction = 2) BigDecimal clerkLimit,
            LocalDate from) {
    }

    /** A grade's clerk limit from a date (missing: the sheet's today); a missing one means the grade uses the
     *  sheet's. */
    public record GradeClerkLimitRequest(@DecimalMin("0.00") @Digits(integer = 13, fraction = 2) BigDecimal clerkLimit,
            LocalDate from) {
    }

    /** The sheet's floor from a date (missing: the sheet's today): the least a claim's live due can be. */
    public record FloorRequest(@NotNull @DecimalMin("0.00") @Digits(integer = 13, fraction = 2) BigDecimal floor,
            LocalDate from) {
    }

    /** The sheet's cap from a date (missing: the sheet's today): the most a person's due-total can be; a
     *  missing one means no cap. */
    public record CapRequest(@DecimalMin("0.00") @Digits(integer = 13, fraction = 2) BigDecimal cap,
            LocalDate from) {
    }

    /** The sheet's proof threshold from a date (missing: the sheet's today); a missing one means none. */
    public record ProofThresholdRequest(@DecimalMin("0.00") @Digits(integer = 13, fraction = 2) BigDecimal proofThreshold,
